    Intake,
    Evidence,
    PolicyReview,
    AwaitingGate,
    Drafting,
    Ready,
    Submitted,
    Approved,
    Denied,
    PeerReview,
    DenialReview,
    ResponseDrafting,
    ResponseReady,
    Resubmitted,
    Appealed,
    Withdrawn,
}

impl CaseStatus {
    pub const fn as_str(self) -> &'static str {
        match self {
            Self::Intake => "intake",
            Self::Evidence => "evidence",
            Self::PolicyReview => "policy_review",
            Self::AwaitingGate => "awaiting_gate",
            Self::Drafting => "drafting",
