            .read_case(&actor, &read_capabilities, create.case_id)
            .await
            .unwrap();
        assert_eq!(created_record.status, CaseStatus::Intake);
        assert_eq!(
            (
                created_record.revision,
                created_record.case_input_revision,
                created_record.status_revision,
            ),
            (1, 1, 0)
