  id               UUID PRIMARY KEY,
  practice_id      UUID NOT NULL,
  document_type_id UUID NOT NULL,
  case_id          UUID,
  name             TEXT NOT NULL,
  effective_date   DATE NOT NULL,
  page_count       INTEGER,
  content_sha256   BYTEA
);

