# ═══════════════════════════════════════════════════════════════════════════
# Prior Authorization Workbench — practice-boundary stack.
#
#   docker compose up -d
#   docker compose down -v      # -v is required to re-run the schema bootstrap
#
# ── The rule this file exists to hold ──────────────────────────────────────
#
# PHI at rest stays inside the practice boundary and inside the United States
# (Texas SB 1188, effective 2026-01-01). No service here moves it outside.
# The only PHI egress in the product is to a BAA-covered inference endpoint
# with zero data retention, gated by Cedar policy — and that service is not in
# this file.
#
# ── One Postgres, several databases ────────────────────────────────────────
#
# flint-forge's postgres18 image is the single instance. It already starts with
# `wal_level=logical` (images/postgres18/Dockerfile:155), which is what Electric
# requires — that is why this image, not `postgres:16-alpine`.
#
# flint-gate's own compose uses postgres:16-alpine. It is a working example, not
# a maintained pin; adapt it rather than copy it.
#
# Kratos owns and migrates its own schema in its own database. `aso.*` must
# never FK into Kratos tables — `users.kratos_identity_id` is a soft reference
# by design (docs/design/schema/schema.sql:230-257).
# ═══════════════════════════════════════════════════════════════════════════

name: aso-prior-auth

services:
  # ── Data plane ───────────────────────────────────────────────────────────
  db:
    build:
      context: ${PROMETHEUS_ROOT:-/Users/gqadonis/Projects/prometheus}/flint-forge
      dockerfile: images/postgres18/Dockerfile
    environment:
      POSTGRES_USER: ${POSTGRES_USER:-flint}
      POSTGRES_PASSWORD: ${POSTGRES_PASSWORD:-flint}
      POSTGRES_DB: ${POSTGRES_DB:-flint}
      # Kratos and flint-gate databases are created by
      # docker/bootstrap/00-create-databases.sh — this image does not implement
      # the POSTGRES_MULTIPLE_DATABASES convention.
    volumes:
      # Postgres 18 changed the volume convention: PGDATA is
      # /var/lib/postgresql/18/docker and the image declares VOLUME
      # /var/lib/postgresql. Mounting at .../data — the pg17-and-earlier path —
      # makes the entrypoint see stray data in an "unused mount/volume" and
      # refuse to start, in a restart loop. Observed 2026-09-05.
      # See docker-library/postgres#1259.
      - db_data:/var/lib/postgresql
      # Bootstrap runs on FIRST START ONLY. Postgres skips this directory when
      # the data volume already exists.
      - ./docker/bootstrap:/docker-entrypoint-initdb.d:ro
      - ./docs/design/schema:/schema:ro
    ports:
      - "${POSTGRES_PORT:-5432}:5432"
    healthcheck:
      test: ["CMD-SHELL", "pg_isready -U ${POSTGRES_USER:-flint} -d ${POSTGRES_DB:-flint}"]
      interval: 5s
      timeout: 5s
      retries: 20
    restart: unless-stopped

  # ── Read-path sync ───────────────────────────────────────────────────────
  # Serves the BASE TABLES. Electric cannot serve a view — measured 2026-09-06:
  #   GET /v1/shape?table=aso.sync_cases -> 400 "does not exist"
  #   GET /v1/shape?table=aso.cases      -> 200                    [control]
  # A view emits no WAL, so it can never join a publication; materialized views
  # fail identically and Postgres refuses them outright. The sync_* views in
  # docker/bootstrap/20-*.sql are SUPERSEDED as the sync path and remain only as
  # documentation plus a PHI assertion over themselves.
  #
  # The tenant boundary is therefore the denormalized, trigger-forced
  # practice_id column (docker/bootstrap/15-*.sql), and the PHI boundary is the
  # per-shape `columns=` projection in web/src/shared/sync/electric-shapes.ts.
  #
  # WARNING: with ELECTRIC_INSECURE and port 3000 published, anything that can
  # reach localhost:3000 can request a base-table shape with no projection and
  # no where-clause. That is acceptable ONLY on a developer machine. A real
  # deployment must not publish this port and must terminate authorization at
  # the gateway.
  electric:
